/** Atelier salon markup applied to workbook base prices */
export const SALON_MARKUP_INR = 28_000;

export function applySalonMarkup(basePriceInr: number): number {
  return basePriceInr + SALON_MARKUP_INR;
}

export function formatRingPriceInr(priceInr: number): string {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 0,
  }).format(priceInr);
}

export function getRingQuote(productCode: string): RingQuote | undefined {
  const base = RING_QUOTES[productCode];
  if (!base) return undefined;
  return { ...base, priceInr: applySalonMarkup(base.priceInr) };
}
